  @RequestMapping(path = "resultsetToExcel", method = RequestMethod.GET)
  public void resultsetToExcel(
      HttpServletRequest req,
      HttpServletResponse response,
      @RequestParam(value = "path", required = false) String path,
      @RequestParam(value = "charset", defaultValue = "utf-8") String charset,
      @RequestParam(value = "outputFileType", defaultValue = "csv") String outputFileType,
      @RequestParam(value = "csvSeperator", defaultValue = ",") String csvSeperator,
      @RequestParam(value = "csvSeparator", defaultValue = ",") String csvSeparator,
      @RequestParam(value = "quoteRetouchEnable", required = false) boolean quoteRetouchEnable,
      @RequestParam(value = "outputFileName", defaultValue = "downloadResultset")
          String outputFileName,
      @RequestParam(value = "sheetName", defaultValue = "result") String sheetName,
      @RequestParam(value = "nullValue", defaultValue = "NULL") String nullValue,
      @RequestParam(value = "limit", defaultValue = "0") Integer limit,
      @RequestParam(value = "autoFormat", defaultValue = "false") Boolean autoFormat,
      @RequestParam(value = "keepNewline", defaultValue = "false") Boolean keepNewline,
      @RequestParam(value = "maskedFieldNames", required = false) String maskedFieldNames)
      throws WorkSpaceException, IOException {
    ServletOutputStream outputStream = null;
    FsWriter fsWriter = null;
    PrintWriter writer = null;
    FileSource fileSource = null;
    if (csvSeparator.equals(",") && !csvSeperator.equals(",")) {
      csvSeparator = csvSeperator;
    }
    LOGGER.info(
        "resultsetToExcel with outputFileType:{}, csvSeparator:{}, quoteRetouchEnable:{}, charset:{}",
        outputFileType,
        csvSeparator,
        quoteRetouchEnable,
        charset);
    try {
      String userName = ModuleUserUtils.getOperationUser(req, "resultsetToExcel " + path);
      LoggerUtils.setJobIdMDC("resultsetToExcelThread_" + userName);
      LOGGER.info("userName {} start to resultsetToExcel File {}", userName, path);
      FsPath fsPath = new FsPath(path);
      FileSystem fileSystem = fsService.getFileSystemForRead(userName, fsPath);
      boolean isLimitDownloadSize = RESULT_SET_DOWNLOAD_IS_LIMIT.getValue();
      Integer csvDownloadSize = RESULT_SET_DOWNLOAD_MAX_SIZE_CSV.getValue();
      Integer excelDownloadSize = RESULT_SET_DOWNLOAD_MAX_SIZE_EXCEL.getValue();
      if (limit > 0) {
        csvDownloadSize = limit;
        excelDownloadSize = limit;
      }

      if (StringUtils.isEmpty(path)) {
        throw WorkspaceExceptionManager.createException(80004, path);
      }
      if (!checkIsUsersDirectory(path, userName)) {
        throw WorkspaceExceptionManager.createException(80010, userName, path);
      }
      response.addHeader(
          "Content-Disposition",
          "attachment;filename="
              + new String(outputFileName.getBytes("UTF-8"), "ISO8859-1")
              + "."
              + outputFileType);
      response.setCharacterEncoding(charset);
      outputStream = response.getOutputStream();
      // 前台传""会自动转为null
      if (nullValue != null && BLANK.equalsIgnoreCase(nullValue)) nullValue = "";
      fileSource = FileSource$.MODULE$.create(fsPath, fileSystem).addParams("nullValue", nullValue);
      switch (outputFileType) {
        case "csv":
          if (FileSource$.MODULE$.isTableResultSet(fileSource)) {
            fsWriter =
                CSVFsWriter.getCSVFSWriter(
                    charset, csvSeparator, quoteRetouchEnable, outputStream, keepNewline);
          } else {
            fsWriter =
                ScriptFsWriter.getScriptFsWriter(new FsPath(outputFileType), charset, outputStream);
          }
          response.addHeader("Content-Type", "text/plain");
          if (isLimitDownloadSize) {
            fileSource = fileSource.page(1, csvDownloadSize);
          }
          break;
        case "xlsx":
          if (!FileSource$.MODULE$.isTableResultSet(fileSource)) {
            throw WorkspaceExceptionManager.createException(80024);
          }
          fsWriter =
              ExcelFsWriter.getExcelFsWriter(
                  charset, sheetName, DEFAULT_DATE_TYPE, outputStream, autoFormat);
          response.addHeader("Content-Type", XLSX_RESPONSE_CONTENT_TYPE);
          if (isLimitDownloadSize) {
            fileSource = fileSource.page(1, excelDownloadSize);
          }
          break;
        default:
          throw WorkspaceExceptionManager.createException(80015);
      }

      // 如果同时提供了字段屏蔽和字段截取参数，则先执行字段屏蔽，再执行字段截取
      if (LinkisStorageConf.FIELD_MASKED_ENABLED()
          && StringUtils.isNotBlank(maskedFieldNames)
          && LinkisStorageConf.FIELD_TRUNCATION_ENABLED()
          && outputFileType.equals("xlsx")) {
        // 同时执行字段屏蔽和字段截取
        StorageExcelWriter excelFsWriter = (StorageExcelWriter) fsWriter;
        ResultUtils.applyFieldMaskingAndTruncation(
            maskedFieldNames,
            excelFsWriter,
            fileSource,
            LinkisStorageConf.FIELD_EXPORT_DOWNLOAD_LENGTH());
      } else if (LinkisStorageConf.FIELD_MASKED_ENABLED()
          && StringUtils.isNotBlank(maskedFieldNames)) {
        // 只执行字段屏蔽
        ResultUtils.dealMaskedField(maskedFieldNames, fsWriter, fileSource);
      } else if (LinkisStorageConf.FIELD_TRUNCATION_ENABLED() && outputFileType.equals("xlsx")) {
        // 只执行字段截取
        StorageExcelWriter excelFsWriter = (StorageExcelWriter) fsWriter;
        ResultUtils.detectAndHandle(
            excelFsWriter, fileSource, LinkisStorageConf.FIELD_EXPORT_DOWNLOAD_LENGTH());
      } else {
        // Original stream write logic
        fileSource.write(fsWriter);
      }
      fsWriter.flush();
      LOGGER.info("userName {} Finished to resultsetToExcel File {}", userName, path);
    } catch (Exception e) {
      LOGGER.error("output failed", e);
      response.reset();
      response.setCharacterEncoding(Consts.UTF_8.toString());
      response.setContentType("text/plain; charset=utf-8");
      writer = response.getWriter();
      writer.append("error(错误):" + e.getMessage());
      writer.flush();
    } finally {
      LoggerUtils.removeJobIdMDC();
      if (outputStream != null) {
        outputStream.flush();
      }
      IOUtils.closeQuietly(fsWriter);
      IOUtils.closeQuietly(fileSource);
      IOUtils.closeQuietly(writer);
    }
  }

@Override
  public boolean onJobFailed(
      Job job, String code, Map<String, Object> props, int errorCode, String errorDesc) {
    if (!EntranceConfiguration.TASK_RETRY_ENABLED()) {
      return false;
    }

    if (!(job instanceof EntranceJob)) {
      return false;
    }

    boolean containsAny = false;
    // 文本匹配
    String errorDescArray = EntranceConfiguration.SUPPORTED_RETRY_ERROR_DESC();
    // 错误码匹配
    String errorCodeArray = EntranceConfiguration.SUPPORTED_RETRY_ERROR_CODES();
    // 正则匹配
    String errorDescRegex = EntranceConfiguration.SUPPORTED_RETRY_ERROR_DESC_REGEX();
    final EntranceJob entranceJob = (EntranceJob) job;
    String engineType = LabelUtil.getEngineType(entranceJob.getJobRequest().getLabels());
    AtomicBoolean canRetry = new AtomicBoolean(false);
    String retryNumKey = EntranceConfiguration.RETRY_NUM_KEY().key();

    if (((Boolean) EntranceConfiguration.TASK_RETRY_SWITCH().getValue())
        && engineType.equals(EngineType.JDBC().toString())
        && StringUtils.isNotBlank(errorDescRegex)) {
      // JDBC执行正则匹配
      for (String regex : errorDescRegex.split(",")) {
        String trimmedRegex = regex.trim();
        if (StringUtils.isNotBlank(trimmedRegex)) {
          try {
            Pattern pattern = Pattern.compile(trimmedRegex, Pattern.CASE_INSENSITIVE);
            if (pattern.matcher(errorDesc).find()) {
              containsAny = true;
              break;
            }
          } catch (Exception e) {
            logger.warn("Invalid regex pattern: {}", trimmedRegex, e);
          }
        }
      }
      if (!containsAny) {
        return false;
      }
      JobRequest jobRequest = entranceJob.getJobRequest();
      Pattern queryPattern =
          Pattern.compile(
              "Query timeout. Increase the query_timeout session variable and retry|Query exceeded time limit of (\\S+) seconds",
              Pattern.CASE_INSENSITIVE);
      Pattern newPlannerPattern =
          Pattern.compile("StarRocks planner use long time", Pattern.CASE_INSENSITIVE);
      Pattern queryQueuePendingPattern =
          Pattern.compile("pending timeout", Pattern.CASE_INSENSITIVE);
      if (queryPattern.matcher(errorDesc).find()) {
        jobRequest.setExecutionCode("SET query_timeout = 1200;\n" + code);
      } else if (newPlannerPattern.matcher(errorDesc).find()) {
        jobRequest.setExecutionCode("SET new_planner_optimize_timeout = 300000;\n" + code);
      } else if (queryQueuePendingPattern.matcher(errorDesc).find()) {
        jobRequest.setExecutionCode("SET query_queue_pending_timeout_second = 3600;\n" + code);
      }
    } else {
      for (String keyword : errorDescArray.split(",")) {
        if (errorDesc.contains(keyword.trim()) || errorCodeArray.contains(errorCode + "")) {
          containsAny = true;
          break;
        }
      }
      if (!containsAny) {
        return false;
      }
      // 处理广播表
      String dataFrameKey = EntranceConfiguration.SUPPORT_ADD_RETRY_CODE_KEYS();
      if (containsAny(errorDesc, dataFrameKey)
          && engineType.equals(EngineType.SPARK().toString())) {
        entranceJob
            .getJobRequest()
            .setExecutionCode("set spark.sql.autoBroadcastJoinThreshold=-1; " + code);
      }
    }

    Map<String, Object> startupMap = TaskUtils.getStartupMap(props);
    String isRetry =
        startupMap
            .getOrDefault(EntranceConfiguration.TASK_RETRY_SWITCH().key(), "false")
            .toString();
    // 对 aiSql 和 starrocks 做重试
    if (Boolean.parseBoolean(isRetry)) {
      LinkisUtils.tryAndWarn(
          () -> {
            int retryNum = (int) startupMap.getOrDefault(retryNumKey, 1);
            boolean canRetryCode = canRetryCode(code);
            if (retryNum > 0 && canRetryCode) {
              logger.info(
                  "mark task: {} status to WaitForRetry, current retryNum: {}, for errorCode: {}, errorDesc: {}",
                  entranceJob.getJobInfo().getId(),
                  retryNum,
                  errorCode,
                  errorDesc);
              // 重试
              job.transitionWaitForRetry();

              // 修改错误码和错误描述
              entranceJob.getJobRequest().setErrorCode(EXEC_FAILED_TO_RETRY.getErrorCode());
              entranceJob.getJobRequest().setErrorDesc(EXEC_FAILED_TO_RETRY.getErrorDesc());
              canRetry.set(true);
              startupMap.put(retryNumKey, retryNum - 1);
              // once 引擎
              if ((boolean) EntranceConfiguration.AI_SQL_RETRY_ONCE().getValue()) {
                // once 引擎
                ExecuteOnceLabel onceLabel =
                    LabelBuilderFactoryContext.getLabelBuilderFactory()
                        .createLabel(ExecuteOnceLabel.class);
                List<Label<?>> labels = entranceJob.getJobRequest().getLabels();
                labels.add(onceLabel);
                logger.info("aisql retry add once label for task id:{}", job.getJobInfo().getId());
                startupMap.put("executeOnce", true);
              }
              TaskUtils.addStartupMap(props, startupMap);
              logger.info("task {} set retry status success.", entranceJob.getJobInfo().getId());
            } else {
              logger.info("task {} not support retry.", entranceJob.getJobInfo().getId());
            }
          },
          logger);
    }
    return canRetry.get();
  }

