      LoggerUtils.setJobIdMDC("resultsetsToExcelThread_" + userName);
      LOGGER.info("userName {} start to resultsetsToExcel File {}", userName, path);
      FsPath fsPath = new FsPath(path);
      FileSystem fileSystem = fsService.getFileSystemForRead(userName, fsPath);
      if (StringUtils.isEmpty(path)) {
        throw WorkspaceExceptionManager.createException(80004, path);
      }
      if (!checkIsUsersDirectory(path, userName)) {
        throw WorkspaceExceptionManager.createException(80010, userName, path);
      }
      // list目录下的文件
      FsPathListWithError fsPathListWithError = fileSystem.listPathWithError(fsPath);
      if (fsPathListWithError == null) {
        throw WorkspaceExceptionManager.createException(80029);
      }

      List<FsPath> fsPathList = fsPathListWithError.getFsPaths();
      // sort asc by _num.dolphin of num
      ResultSetUtils.sortByNameNum(fsPathList);
      FsPath[] fsPaths = fsPathList.toArray(new FsPath[] {});

      boolean isLimitDownloadSize = RESULT_SET_DOWNLOAD_IS_LIMIT.getValue();
      Integer excelDownloadSize = RESULT_SET_DOWNLOAD_MAX_SIZE_EXCEL.getValue();
      if (limit > 0) {
        excelDownloadSize = limit;
      }
      response.addHeader(
          "Content-Disposition",
          "attachment;filename="
              + new String(outputFileName.getBytes(StandardCharsets.UTF_8), "ISO8859-1")
              + ".xlsx");
      response.setCharacterEncoding(StandardCharsets.UTF_8.name());
      outputStream = response.getOutputStream();
      // 前台传""会自动转为null
      if (nullValue != null && BLANK.equalsIgnoreCase(nullValue)) {
        nullValue = "";
      }
      fileSource =
          FileSource$.MODULE$.create(fsPaths, fileSystem).addParams("nullValue", nullValue);
      if (!FileSource$.MODULE$.isTableResultSet(fileSource)) {
        throw WorkspaceExceptionManager.createException(80024);
      }
      fsWriter = new StorageMultiExcelWriter(outputStream, autoFormat);
      response.addHeader("Content-Type", XLSX_RESPONSE_CONTENT_TYPE);
      if (isLimitDownloadSize) {
        fileSource = fileSource.page(1, excelDownloadSize);
      }
      // 如果同时提供了字段屏蔽和字段截取参数，则先执行字段屏蔽，再执行字段截取
      if (LinkisStorageConf.FIELD_MASKED_ENABLED()
          && StringUtils.isNotBlank(maskedFieldNames)
          && LinkisStorageConf.FIELD_TRUNCATION_ENABLED()) {
        // 同时执行字段屏蔽和字段截取
        StorageExcelWriter excelFsWriter = (StorageExcelWriter) fsWriter;
        ResultUtils.applyFieldMaskingAndTruncation(
            maskedFieldNames,
            excelFsWriter,
            fileSource,
            LinkisStorageConf.FIELD_EXPORT_MAX_LENGTH());
      } else if (LinkisStorageConf.FIELD_MASKED_ENABLED()
          && StringUtils.isNotBlank(maskedFieldNames)) {
        // 只执行字段屏蔽
        ResultUtils.dealMaskedField(maskedFieldNames, fsWriter, fileSource);
      } else if (LinkisStorageConf.FIELD_TRUNCATION_ENABLED()) {
        // 只执行字段截取
        StorageExcelWriter excelFsWriter = (StorageExcelWriter) fsWriter;
        ResultUtils.detectAndHandle(
            excelFsWriter, fileSource, LinkisStorageConf.FIELD_EXPORT_DOWNLOAD_LENGTH());
      } else {
        // Original stream write logic
        fileSource.write(fsWriter);
      }
      fsWriter.flush();
      LOGGER.info("userName {} Finished to resultsetsToExcel File {}", userName, path);
    } catch (Exception e) {
      LOGGER.error("output failed", e);
      response.reset();
      response.setCharacterEncoding(Consts.UTF_8.toString());
      response.setContentType("text/plain; charset=utf-8");
      writer = response.getWriter();
      writer.append("error(错误):" + e.getMessage());
      writer.flush();
    } finally {
      LoggerUtils.removeJobIdMDC();
      if (outputStream != null) {
        outputStream.flush();
      }
      IOUtils.closeQuietly(fsWriter);
      IOUtils.closeQuietly(fileSource);
      IOUtils.closeQuietly(writer);
    }
  }

@ApiOperation(
      value = "diagnosis-query",
      notes = "query failed task diagnosis msg",
      response = Message.class)
  @ApiImplicitParams({
    @ApiImplicitParam(name = "taskID", dataType = "String"),
    @ApiImplicitParam(name = "diagnosisSource", dataType = "String", example = "doctoris"),
  })
  @RequestMapping(path = "/diagnosis-query", method = RequestMethod.GET)
  public Message queryFailedTaskDiagnosis(
      HttpServletRequest req,
      @RequestParam(value = "taskID", required = false) String taskID,
      @RequestParam(value = "diagnosisSource", required = false) String diagnosisSource) {
    String username = ModuleUserUtils.getOperationUser(req, "diagnosis-query");
    if (StringUtils.isBlank(taskID)) {
      return Message.error("Invalid jobId cannot be empty");
    }
    if (!QueryUtils.checkNumberValid(taskID)) {
      throw new LinkisCommonErrorException(21304, "Invalid taskID : " + taskID);
    }
    if (StringUtils.isBlank(diagnosisSource)) {
      diagnosisSource = "linkis";
    }
    JobHistory jobHistory = null;
    boolean isAdmin = Configuration.isJobHistoryAdmin(username) || Configuration.isAdmin(username);
    boolean isDepartmentAdmin = Configuration.isDepartmentAdmin(username);
    if (isAdmin) {
      jobHistory = jobHistoryQueryService.getJobHistoryByIdAndName(Long.valueOf(taskID), null);
    } else if (isDepartmentAdmin) {
      String departmentId = JobhistoryUtils.getDepartmentByuser(username);
      if (StringUtils.isNotBlank(departmentId)) {
        List<JobHistory> list =
            jobHistoryQueryService.search(
                Long.valueOf(taskID),
                null,
                null,
                null,
                null,
                null,
                null,
                null,
                null,
                departmentId,
                null,
                null);
        if (!CollectionUtils.isEmpty(list)) {
          jobHistory = list.get(0);
        }
      }
    } else {
      jobHistory = jobHistoryQueryService.getJobHistoryByIdAndName(Long.valueOf(taskID), username);
    }
    String diagnosisMsg = "";
    if (jobHistory != null) {
      String jobStatus = jobHistory.getStatus();
      JobDiagnosis jobDiagnosis =
          jobHistoryDiagnosisService.selectByJobId(Long.valueOf(taskID), diagnosisSource);
      if (null == jobDiagnosis) {
        if (diagnosisSource.equals("doctoris")) {
          return Message.ok().data("diagnosisMsg", diagnosisMsg);
        }
        diagnosisMsg = JobhistoryUtils.getDiagnosisMsg(taskID);
        jobDiagnosis = new JobDiagnosis();
        jobDiagnosis.setJobHistoryId(Long.valueOf(taskID));
        jobDiagnosis.setDiagnosisContent(diagnosisMsg);
        jobDiagnosis.setCreatedTime(new Date());
        jobDiagnosis.setUpdatedDate(new Date());
        jobDiagnosis.setDiagnosisSource("linkis");
        if (TaskStatus.isComplete(TaskStatus.valueOf(jobStatus))) {
          jobDiagnosis.setOnlyRead("1");
        }
        jobHistoryDiagnosisService.insert(jobDiagnosis);
      } else {
        if (StringUtils.isNotBlank(jobDiagnosis.getOnlyRead())
            && "1".equals(jobDiagnosis.getOnlyRead())) {
          diagnosisMsg = jobDiagnosis.getDiagnosisContent();
        } else {
          diagnosisMsg = JobhistoryUtils.getDiagnosisMsg(taskID);
          jobDiagnosis.setDiagnosisContent(diagnosisMsg);
          jobDiagnosis.setUpdatedDate(new Date());
          jobDiagnosis.setDiagnosisContent(diagnosisMsg);
          if (TaskStatus.isComplete(TaskStatus.valueOf(jobStatus))) {
            jobDiagnosis.setOnlyRead("1");
          }
          jobHistoryDiagnosisService.update(jobDiagnosis);
        }
      }
    }
    return Message.ok().data("diagnosisMsg", diagnosisMsg);
  }
